{"l":9300,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord passer: 'The council has ___ a ban on cars in the old town centre.'","o":["opposed","exposed","composed","imposed"],"a":"imposed","r":"'Impose a ban' betyder at indføre et forbud. 'Opposed' betyder at være imod, hvilket ikke passer med 'a ban on'."},
{"l":9310,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'omfattende' på engelsk?","o":["comprehensive","comprehensible","apprehensive","competitive"],"a":"comprehensive","r":"'Comprehensive' betyder omfattende. Forståelig hedder 'comprehensible'."},
{"l":9310,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Although Maya claims she hardly studied, her notebooks are full of colour-coded summaries and practice essays.' Hvad antyder teksten om Maya?","o":["At hun ikke har lavet noget","At hun har arbejdet mere, end hun siger","At hun er dårlig til at tegne","At hun har lånt en andens noter"],"a":"At hun har arbejdet mere, end hun siger","r":"'Although' viser en modsætning: hun siger, hun næsten ikke har læst, men noterne viser det modsatte."},
{"l":9330,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'Little ___ that her quiet classmate would become a famous author.'","o":["she knew","knew she","did she know","she did know"],"a":"did she know","r":"'Little' først i sætningen med betydningen 'slet ikke' kræver inversion med 'did': 'Little did she know'."},
{"l":9333,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'med vilje' på engelsk?","o":["desperately","delicately","definitely","deliberately"],"a":"deliberately","r":"'Deliberately' betyder med vilje."},
{"l":9344,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'ugunstig' på engelsk i '___ weather conditions'?","o":["adverse","averse","diverse","inverse"],"a":"adverse","r":"'Adverse' betyder ugunstig."},
{"l":9356,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'bekræfte / støtte op om' på engelsk?","o":["collaborate","corroborate","commemorate","coordinate"],"a":"corroborate","r":"'Corroborate' = bekræfte med yderligere beviser."},
{"l":9360,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord passer: 'The comment from the teacher ___ a heated debate in the classroom.'","o":["sparkled","spotted","sparked","sparred"],"a":"sparked","r":"'Spark a debate' betyder at sætte gang i en diskussion. 'Sparkled' betyder funklede."},
{"l":9370,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder det modsatte af 'mundane' i 'mundane tasks'?","o":["practical","domestic","repetitive","extraordinary"],"a":"extraordinary","r":"'Mundane' betyder hverdagsagtig og kedelig, så det modsatte er 'extraordinary' (usædvanlig)."},
{"l":9381,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'adskilte / særskilte' på engelsk?","o":["discrete","discreet","concrete","obsolete"],"a":"discrete","r":"'Discrete' betyder adskilt."},
{"l":9400,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","variant":"authored","q":"Hvad siger man på engelsk, når man vil bede om lidt betænkningstid til i morgen, før man svarer?","o":["Let me take it easy.","Let me sleep on it.","Let me give it up.","Let me get over it."],"a":"Let me sleep on it.","r":"'Let me sleep on it' betyder, at man vil tænke over det til næste dag. 'Get over it' betyder at komme sig over noget."},
{"l":9414,"g":9,"b":3,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'bagklogskab' på engelsk?","o":["foresight","insight","hindsight","eyesight"],"a":"hindsight","r":"'In hindsight' = set i bakspejlet."},
{"l":9440,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder 'eclectic' i 'Her taste in music is very eclectic.'?","o":["gammeldags","snæver","støjende","alsidig"],"a":"alsidig","r":"'Eclectic' betyder alsidig og sammensat af mange forskellige stilarter."},
{"l":9470,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad hedder 'fritaget' på engelsk i 'Pupils with a doctor's note are ___ from swimming lessons.'?","o":["exempt","expelled","exposed","extended"],"a":"exempt","r":"'Exempt from' betyder fritaget for. 'Expelled' betyder bortvist, hvilket er noget helt andet."},
{"l":9500,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'So quickly ___ that nobody noticed her leave.'","o":["she moved","did she move","moved she","she did move"],"a":"did she move","r":"Når 'So + biord' står først med 'that', bruges inversion med 'did': 'So quickly did she move'."},
{"l":9530,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'No sooner had the match started ___ it began to pour with rain.'","o":["when","then","than","that"],"a":"than","r":"Det faste mønster er 'No sooner had ... than ...'. 'When' bruges i stedet med 'Hardly' eller 'Scarcely'."},
{"l":9560,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad hedder 'overdreven' på engelsk i 'Spending ___ amounts of time online can affect your sleep.'?","o":["expressive","exclusive","exhaustive","excessive"],"a":"excessive","r":"'Excessive' betyder overdreven. 'Exclusive' betyder eksklusiv, og 'exhaustive' betyder udtømmende."},
{"l":9580,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder det modsatte af 'covert' i 'a covert glance'?","o":["overt","nervous","quick","friendly"],"a":"overt","r":"'Covert' betyder skjult eller hemmelig, så det modsatte er 'overt' (åbenlys)."},
{"l":9600,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder det modsatte af 'tardy' i 'a tardy reply'?","o":["polite","prompt","rude","short"],"a":"prompt","r":"'Tardy' betyder sen eller forsinket, så det modsatte er 'prompt' (hurtig, rettidig)."},
{"l":9620,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord passer: 'Passengers are kindly requested to ___ from smoking on board.'","o":["prevent","resist","refrain","stop"],"a":"refrain","r":"'Refrain from' er et formelt udtryk for at afholde sig fra noget. De andre verber kan ikke stå med 'from' på denne måde."},
{"l":9640,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'The bridge is thought ___ in the twelfth century.'","o":["to be built","having been built","to build","to have been built"],"a":"to have been built","r":"Broen blev bygget i fortiden og er passiv, så man bruger perfektum-passiv infinitiv: 'to have been built'."},
{"l":9680,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"h","variant":"authored","q":"Hvad betyder 'well under way' i 'Preparations for the school festival are already well under way.'?","o":["i fuld gang","helt forsinkede","næsten aflyste","slet ikke startet"],"a":"i fuld gang","r":"'Well under way' betyder, at noget allerede er godt i gang."},
{"l":9705,"g":9,"b":4,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'at ændre reglerne undervejs' på engelsk?","o":["to move the needle","to move the goalposts","to shift the blame","to score an own goal"],"a":"to move the goalposts","r":"'to move the goalposts' betyder at ændre reglerne undervejs. Udtrykket bruges, når nogen ændrer betingelserne uretfærdigt."},
{"l":9720,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder det modsatte af 'fertile' i 'fertile soil'?","o":["sandy","dark","barren","deep"],"a":"barren","r":"'Fertile' betyder frugtbar, så det modsatte er 'barren' (gold, ufrugtbar)."},
{"l":9750,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"g","variant":"authored","q":"Hvilket ord passer: 'The teacher demanded that the noise ___ immediately.'","o":["stopping","to stop","being stopped","stop"],"a":"stop","r":"Efter 'demand that' bruges konjunktiv: grundformen 'stop' uden endelse."},
{"l":9775,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'at være i strid' på engelsk?","o":["to be at loggerheads","to be at a loss","to be at large","to be on the same page"],"a":"to be at loggerheads","r":"'to be at loggerheads' betyder at være i strid. Udtrykket betyder at være uenige og i konflikt."},
{"l":9800,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'The museum guide spoke so quietly that, by the end of the tour, most of the group had drifted off to look at the paintings on their own.' Hvad kan man udlede af teksten?","o":["Guiden var vred på gruppen","De fleste kunne ikke høre guiden ordentligt","Gruppen interesserede sig ikke for malerier","Rundvisningen sluttede alt for tidligt"],"a":"De fleste kunne ikke høre guiden ordentligt","r":"Guiden talte så lavt, at gruppen gled væk og kiggede selv; man kan udlede, at de ikke kunne høre hende."},
{"l":9820,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord passer: 'Pupils must ___ a balance between schoolwork and free time.'","o":["make","hit","strike","beat"],"a":"strike","r":"Den faste forbindelse er 'strike a balance' (finde den rette balance)."},
{"l":9850,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Every single one of the eggs survived the drop, which is more than can be said for Mr Hansen and his lab coat.' Hvad kan man udlede af teksten?","o":["At alle æggene gik i stykker til sidst","At læreren fik en ny kittel af klassen","At forsøget blev aflyst på grund af ham","At det gik værre for læreren end for æggene"],"a":"At det gik værre for læreren end for æggene","r":"'Which is more than can be said for' betyder, at det samme ikke gjaldt for hr. Hansen og hans kittel; han klarede sig dårligere end æggene."},
{"l":9880,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'gregarious' i 'a gregarious person'?","o":["sociable","generous","stubborn","gorgeous"],"a":"sociable","r":"'Gregarious' betyder selskabelig og glad for andres selskab, altså 'sociable'."},
{"l":9900,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvilket ord betyder næsten det samme som 'concur' i 'concur with the expert'?","o":["argue","agree","compete","consult"],"a":"agree","r":"'Concur' er et formelt ord for at være enig, altså 'agree'."},
{"l":9950,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"authored","q":"Hvad betyder 'precarious' i 'The climber found himself in a precarious position on the narrow ledge.'?","o":["behagelig","ensom","farefuld","heldig"],"a":"farefuld","r":"'Precarious' betyder usikker og farefuld; klatreren stod på en smal afsats."},
{"l":9970,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'Not that I am complaining, but this is the third time this month that my order has arrived broken.' Hvad er skribentens egentlige hensigt?","o":["At rose den hurtige levering","At bestille noget nyt hos firmaet","At takke for en god service","At klage, selv om det nægtes"],"a":"At klage, selv om det nægtes","r":"'Not that I am complaining, but' indleder typisk netop en klage; skribenten klager over ødelagte varer."},
{"l":9990,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"l","variant":"authored","q":"Læs: 'While the new app is undeniably convenient, one cannot help wondering how much of our personal data it quietly collects.' Hvilken holdning har skribenten til appen?","o":["Positiv, men også skeptisk","Udelukkende begejstret","Helt ligeglad","Meget vred"],"a":"Positiv, men også skeptisk","r":"'Undeniably convenient' er positivt, men 'cannot help wondering' viser skepsis over for dataindsamlingen."},
{"l":10000,"g":9,"b":5,"cefr":"C1","role":"deep_challenge","insight":"perspective_shift","k":"o","variant":"reverse_meaning","q":"Hvad hedder 'stille op over for hinanden' på engelsk?","o":["transpose","juxtapose","expose","propose"],"a":"juxtapose","r":"'Juxtapose' = sidestille for at vise kontrast."}
]$$::jsonb) AS e
JOIN (VALUES
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('h', 'hverdagsudtryk', 'comprehension', 'conceptual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
